-- देश के विधानसभा क्षेत्रों की सूची (चुनने के लिए)।
-- स्रोत: DataMeet "India - Assembly Constituencies" (ECI से; CC BY 2.5 India), 2008 परिसीमन।
-- ज़िले उस समय के नाम से हैं (बाद में बने नए ज़िले नहीं)। जम्मू-कश्मीर व असम छोड़े गए (वहाँ 2022 / 2023 में नया परिसीमन हुआ)।
-- छत्तीसगढ़ के 90 क्षेत्रों के नाम हिंदी में भी; बाकी राज्यों के अंग्रेज़ी में। आंध्र प्रदेश के क्रमांक पुराने (संयुक्त आंध्र) वाले।
create table if not exists public.assembly_constituencies (
  id serial primary key,
  state text not null,
  district text,
  ac_no int not null,
  name text not null,
  name_hi text,
  district_hi text,
  reserved text,
  pc_name text,
  unique (state, ac_no)
);
alter table public.assembly_constituencies enable row level security;
drop policy if exists ac_read on public.assembly_constituencies;
create policy ac_read on public.assembly_constituencies for select to anon, authenticated using (true);
grant select on public.assembly_constituencies to anon, authenticated;

